        SET  ACTION_YN    = 'N'
        WHERE NOTI_SEQ    = #{notiSeq} 
		  AND FILE_GB     = #{fileGb} 
          AND ACTION_YN = 'Y'

mapper.insert:
        INSERT INTO TBL_FILE_MST (
	         FILE_SEQ   
	        ,FILE_GB  
	        ,FILE_TITLE  
	        ,FILE_PATH  
	        ,HOSP_CD 
	        ,USE_YN  
	        ,REG_DTTM 
	        ,REG_USER  
	        ,REG_IP  
	        ,UPD_DTTM 
	        ,UPD_USER  
	        ,UPD_IP 
            ,JOB_SEQ
            ,ACTION_YN
        ) VALUES (
             #{fileSeq}  
	        ,#{fileGb}   
	        ,#{fileTitle} 
		    ,#{filePath} 
	        ,#{hospCd}  
	        ,#{useYn}  
	        ,NOW() 
	        ,#{regUser}  
	        ,#{regIp}  
	        ,NOW() 
	        ,#{updUser}  
	        ,#{updIp} 
			,(SELECT CASE WHEN MAX(A.JOB_SEQ) IS NOT NULL THEN MAX(A.JOB_SEQ) + 1 ELSE 1 END
		   	       FROM  TBL_FILE_MST A 
			       WHERE A.FILE_SEQ   = #{fileSeq} 
			         AND A.FILE_GB    = #{fileGb} 
			) , 'Y'
        )

mapper.update:
        UPDATE TBL_FILE_MST
        SET  ACTION_YN     = 'N'
            ,UPD_DTTM      = NOW()
            ,UPD_USER      = #{updUser}
            ,UPD_IP        = #{updIp}
        WHERE FILE_SEQ     = #{fileSeq} 
		  AND FILE_GB      = #{fileGb} 
          AND ACTION_YN    = 'Y' 



           AND   A.HOSP_CD = #{hospCd}

        UPDATE TBL_FILE_MST
         SET  FILE_PATH     = #{filePath}
        WHERE FILE_SEQ     = #{fileSeq} 
		  AND FILE_GB      = #{fileGb} 
		  AND SEQ          = #{seq} 
          AND ACTION_YN    = 'Y'

        UPDATE TBL_FILE_MST
        SET  ACTION_YN   = 'N'
            ,UPD_DTTM    = NOW()
            ,UPD_USER    = #{updUser}
            ,UPD_IP      = #{updIp}
        WHERE FILE_SEQ   = #{fileSeq} 
		  AND FILE_GB    = #{fileGb} 
		  AND FILE_PATH  = #{filePath}
          AND ACTION_YN  = 'Y' 



           AND   A.HOSP_CD = #{hospCd}

        UPDATE TBL_ASQ_MST
        SET  ANSR_WAN     = #{ansrWan}  
            ,ANSR_CONTS   = #{ansrConts}
            ,ANSR_READ_YN = CASE WHEN #{ansrWan} = 'Y' THEN 'N' ELSE IFNULL(ANSR_READ_YN,'N') END           
            ,UPD_DTTM     = NOW()
            ,UPD_USER     = #{updUser}
            ,UPD_IP       = #{updIp}
        WHERE ASQ_SEQ     = #{asqSeq} 
		  AND FILE_GB     = #{fileGb} 
          AND ACTION_YN   = 'Y'

UPDATE TBL_ASQ_MST
SET  QSTN_TITLE   = #{qstnTitle}
    ,QSTN_CONTS   = #{qstnConts}
    ,UPD_DTTM     = NOW()
    ,UPD_USER     = #{updUser}
    ,UPD_IP       = #{updIp}
    ,QSTN_WAN     = #{qstnWan}
WHERE ASQ_SEQ     = #{asqSeq}
  AND FILE_GB     = #{fileGb}
  AND ACTION_YN   = 'Y'

        UPDATE TBL_ASQ_MST
        SET  ACTION_YN    = 'N'          
            ,UPD_DTTM     = NOW()
            ,UPD_USER     = #{updUser}
            ,UPD_IP       = #{updIp}
        WHERE ASQ_SEQ     = #{asqSeq}
		  AND FILE_GB     = #{fileGb}
          AND ACTION_YN   = 'Y'

UPDATE TBL_VISITASQ_MST
SET  COMFORM_YN = #{comformYn}
    ,UPD_DTTM   = NOW()
WHERE SEQ       = #{seq}
  AND ACTION_YN = 'Y'

UPDATE TBL_QNA_KB
   SET TITLE  = #{title}
      ,BODY   = #{body}
      ,CAT_ID = #{catId}
      ,KIND   = 'HTML'   /* 편집기가 서식(HTML)으로 저장한다 — 표시도 HTML 로 (2026-08-26) */
 WHERE KB_ID  = #{kbId}

mapper.select:
SELECT K.KB_ID AS kbId ,K.KB_CODE AS kbCode ,K.TITLE AS title ,IFNULL(NULLIF(K.SHORT_TITLE,''),K.TITLE) AS shortTitle ,K.SRC_TYPE AS srcType ,K.KIND AS kind ,K.SUB_ID AS subId ,K.HIT_CNT AS hitCnt FROM TBL_QNA_KB K WHERE K.USE_YN = 'Y'
AND K.CAT_ID = #{catId}
AND K.SUB_ID = #{subId}
ORDER BY K.SORT_NO, K.KB_ID

SELECT K.KB_ID AS kbId ,K.KB_CODE AS kbCode ,K.CAT_ID AS catId ,K.SUB_ID AS subId ,K.SRC_TYPE AS srcType ,K.KIND AS kind ,K.TITLE AS title ,K.BODY AS body ,K.GO_JSON AS goJson ,K.REL_IDS AS relIds ,K.SRC_NM AS srcNm ,K.DOC_PAGE AS docPage ,K.HIT_CNT AS hitCnt ,C.CAT_NM AS catNm ,S.CAT_NM AS subNm FROM TBL_QNA_KB K LEFT JOIN TBL_QNA_CAT C ON C.CAT_ID = K.CAT_ID LEFT JOIN TBL_QNA_CAT S ON S.CAT_ID = K.SUB_ID WHERE K.USE_YN = 'Y'
AND K.KB_ID = #{kbId}
AND K.KB_CODE = #{kbCode}
LIMIT 1

SELECT K.KB_ID AS kbId ,K.KB_CODE AS kbCode ,K.TITLE AS title ,IFNULL(NULLIF(K.SHORT_TITLE,''),K.TITLE) AS shortTitle ,K.CAT_ID AS catId ,K.SRC_TYPE AS srcType ,K.KIND AS kind ,K.DOC_PAGE AS docPage ,C.CAT_NM AS catNm ,( MATCH(K.TITLE,K.KEYWORDS,K.BODY) AGAINST (#{q} IN NATURAL LANGUAGE MODE) + CASE WHEN K.TITLE LIKE CONCAT('%',#{q},'%') THEN 14 ELSE 0 END + CASE WHEN K.KEYWORDS LIKE CONCAT('%',#{q},'%') THEN 6 ELSE 0 END + CASE WHEN K.BODY LIKE CONCAT('%',#{q},'%') THEN 3 ELSE 0 END
+ CASE WHEN K.TITLE LIKE CONCAT('%',#{w},'%') THEN 10 ELSE 0 END + CASE WHEN K.KEYWORDS LIKE CONCAT('%',#{w},'%') THEN 5 ELSE 0 END
+ (K.WEIGHT / 2) + LEAST(K.HIT_CNT,20) / 10 ) AS score /* 검색어 낱말 중 [제목·키워드에 실제로 걸린 개수] (2026-08-06) ★순위용이 아니라 [제대로 찾았는지] 판정용이다. ngram 전문색인은 '오래'·'점수' 같은 조각에도 걸려서 엉뚱한 항목이 30건씩 잡히고 0건이 안 난다. 그래서 "0건일 때만 AI" 로는 AI 가 영영 안 뜬다. 낱말이 절반도 안 걸렸으면 [못 찾은 것]으로 보고 AI 참고답변으로 넘긴다. */ ,( 0
+ CASE WHEN K.TITLE LIKE CONCAT('%',#{w},'%') OR K.KEYWORDS LIKE CONCAT('%',#{w},'%') THEN 1 ELSE 0 END
) AS wHit FROM TBL_QNA_KB K LEFT JOIN TBL_QNA_CAT C ON C.CAT_ID = K.CAT_ID WHERE K.USE_YN = 'Y' AND ( MATCH(K.TITLE,K.KEYWORDS,K.BODY) AGAINST (#{q} IN NATURAL LANGUAGE MODE) OR K.TITLE LIKE CONCAT('%',#{q},'%') OR K.KEYWORDS LIKE CONCAT('%',#{q},'%') OR K.BODY LIKE CONCAT('%',#{q},'%') ) ORDER BY score DESC, K.WEIGHT DESC, K.HIT_CNT DESC LIMIT #{listCnt}

SELECT K.KB_ID AS kbId ,K.TITLE AS title ,C.CAT_NM AS catNm ,LEFT(K.BODY, 1200) AS body ,( MATCH(K.TITLE,K.KEYWORDS,K.BODY) AGAINST (#{q} IN NATURAL LANGUAGE MODE) + CASE WHEN K.TITLE LIKE CONCAT('%',#{q},'%') THEN 14 ELSE 0 END + CASE WHEN K.KEYWORDS LIKE CONCAT('%',#{q},'%') THEN 6 ELSE 0 END
+ CASE WHEN K.TITLE LIKE CONCAT('%',#{w},'%') THEN 10 ELSE 0 END + CASE WHEN K.KEYWORDS LIKE CONCAT('%',#{w},'%') THEN 5 ELSE 0 END + CASE WHEN K.BODY LIKE CONCAT('%',#{w},'%') THEN 2 ELSE 0 END
+ (K.WEIGHT / 2) ) AS score FROM TBL_QNA_KB K LEFT JOIN TBL_QNA_CAT C ON C.CAT_ID = K.CAT_ID WHERE K.USE_YN = 'Y' AND ( MATCH(K.TITLE,K.KEYWORDS,K.BODY) AGAINST (#{q} IN NATURAL LANGUAGE MODE) OR K.TITLE LIKE CONCAT('%',#{q},'%') OR K.KEYWORDS LIKE CONCAT('%',#{q},'%')
OR K.TITLE LIKE CONCAT('%',#{w},'%') OR K.KEYWORDS LIKE CONCAT('%',#{w},'%') OR K.BODY LIKE CONCAT('%',#{w},'%')
) ORDER BY score DESC, K.WEIGHT DESC, K.HIT_CNT DESC LIMIT #{listCnt}
